mapper.select:
select ,
from CHB_FEEDBACK_FILE cff where 1=1
AND cff.REPORT_ETR_TYPE = #{reportEtrType}
AND cff.HANDLE_STATUS = #{handleStatus}
AND cff.REPORT_SEND_DATE >= TO_DATE(#{reportSendDate}, 'yyyy-MM-dd HH24:mi:ss')
AND cff.REPORT_ACCEPT_DATE >= TO_DATE(#{reportAcceptDate}, 'yyyy-MM-dd HH24:mi:ss')

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, ASSET_CODE||','||TO_CHAR(VAL_DATE, 'yyyy-MM-dd') keyCode from CHB_AST_VAL_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_REGIST_CODE keyCode from CHB_PRD_ISSUE_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_INS_ID keyCode from CHB_PRD_DECLARE_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_ID keyCode from CHB_PRD_RAISETOT_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_REGIST_CODE||','||TO_CHAR(MDATE, 'yyyy-MM-dd') keyCode from CHB_PRD_DEAL_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_REGIST_CODE keyCode from CHB_PRD_END_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PLAN_ASSET_ID||','||ASSET_CODE||','||TO_CHAR(POS_DATE, 'yyyy-MM-dd') keyCode from CHB_BOT_AST_POS_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, TRADE_CODE keyCode from CHB_INVEST_TRADE_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, ASSET_CODE keyCode from CHB_ASSET_INFO_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, EMPLOYEE_TYPE||','||IDENTIFY_NUMBER keyCode from CHB_EMPLOYEE_INFO_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ
